hooks.command:
python3 -c "import json,os,sys
p=os.path.expanduser('~/.claude/plugins/installed_plugins.json')
try:
 v=[i.get('version','0') for i in json.load(open(p))['plugins']['bd@bydefault']][0]
except Exception:
 v=None
def t(x): return tuple(int(n) for n in x.split('.')[:3])
if v is None: m='The bd plugin is not installed on this machine. This template assumes bd 0.5.0 or later for /bd:kickoff, /bd:handover and /bd:localhost. Tell the user to run, in the terminal app: /plugin marketplace add bydefaultstudio/agents then /plugin install bd@bydefault, then start a fresh session.'
elif t(v) < t('0.5.0'): m='The bd plugin is installed at '+v+' but this template assumes 0.5.0 or later. Tell the user to run /plugin update bd in the terminal app, then start a fresh session.'
else: sys.exit(0)
print(json.dumps({'hookSpecificOutput':{'hookEventName':'SessionStart','additionalContext':m}}))" 2>/dev/null || true
